INSERT INTO `pasal-kontrak` (`id`, `nama_pasal`, `keterangan_pasal`, `isi_pasal`, `jenis_pasal`, `created_at`, `updated_at`) VALUES
(1, 'PASAL 1', 'DEFINISI-DEFINISI', '(1)Perjanjian adalah Perjanjian ini yang dibuat dan ditandatangani antara Para Pihak, termasuk seluruh lampirannya dan setiap perubahan-perubahannya.\r\n(2)Barang adalah Pengadaan barang yang harus diadakan dan dipasok oleh PIHAK KEDUA.\r\n(3)Spesifikasi Teknis adalah Spesifikasi Teknis barang yang telah disepakati bersama oleh para pihak sebagaimana dimaksud dalam Lampiran III Perjanjian ini.\r\n(4)Bulan dan Hari adalah bulan dan hari terkait yang tercantum dalam kalender Masehi.\r\n(5)Tanggal Berlakunya Perjanjian adalah tanggal dimana semua ketentuan yang terdapat pada Pasal 22 terpenuhi.\r\n(6)Surat Penerimaan Barang (SPB) adalah pernyataan tertulis bertanggal dan diterbitkan oleh PIHAK KESATU yang menyatakan bahwa barang telah diserahkan dan diterima oleh PIHAK KESATU sesuai dengan Perjanjian.\r\n(7)Jaminan Mutu adalah kewajiban PIHAK KEDUA untuk menjaga kualitas barang selama masa tertentu sebagaimana diatur dalam Perjanjian ini. ', 1, '2024-03-08 06:04:11', '2024-03-08 07:21:21'),
(2, 'PASAL 2', 'KETENTUAN-KETENTUAN UMUM', '(1)Apabila suatu ketentuan Perjanjian ini atau bagian dari padanya dianggap batal, tidak sah atau tidak dapat diberlakukan berdasarkan peraturan perundang-undangan yang berlaku terhadap mana ketentuan tersebut tunduk, maka ketentuan dimaksud dianggap batal, tidak sah atau tidak dapat diberlakukan dengan cara apapun, tidak berpengaruh pada atau mengurangi berlakunya bagian lain dari ketentuan tersebut atau ketentuan-ketentuan lainnya dari Perjanjian ini.\r\n(2)Kelalaian salah satu Pihak dalam melaksanakan, dan keterlambatan satu Pihak melaksanakan hak berdasarkan Perjanjian ini, tidak berlaku sebagai pembebasan atau pengesampingan dari setiap pelaksanaan keseluruhan atau sebagian dari hak berdasarkan Perjanjian ini tidak mencegah pelaksanaan lain atau pelaksanaan selanjutnya dari hak tersebut.\r\n(3)Perjanjian ini berlaku untuk kepentingan dan mengikat Para Pihak, para pengganti dan para penerima hak yang diijinkan masing-masing Pihak.', 1, '2024-03-08 06:04:11', '2024-03-08 07:21:24'),
(3, 'PASAL 3', 'LINGKUP PERJANJIAN', 'Lingkup Perjanjian sebagaimana tercantum pada Lampiran II Perjanjian ini.', 1, '2024-03-08 06:04:11', '2024-03-08 07:21:27'),
(4, 'PASAL 4', 'SPESIFIKASI TEKNIS', 'Spesifikasi teknis barang sebagaimana tercantum dalam Lampiran III Perjanjian ini.', 1, '2024-03-08 06:04:11', '2024-03-08 07:21:29'),
(5, 'PASAL 5', 'JADWAL PENYERAHAN BARANG', 'Jadwal penyerahan barang sebagaimana dimaksud dalam Lampiran IV Perjanjian ini.', 1, '2024-03-08 06:04:11', '2024-03-08 07:21:31'),
(6, 'PASAL 6', 'PERUBAHAN JADWAL PENYERAHAN BARANG', '(1)Jadwal penyerahan barang dimaksud Pasal 5 Perjanjian ini dapat berubah sewaktu-waktu sesuai permintaan PIHAK KESATU, yang mana permintaan tersebut dibuat secara tertulis oleh dan dari PIHAK KESATU kepada PIHAK KEDUA.\r\n(2)Perubahan dimaksud ayat (1) Pasal ini akan dituangkan dalam suatu Addendum Lampiran IV, yang merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.\r\n', 1, '2024-03-08 06:04:11', '2024-03-08 07:21:34'),
(7, 'PASAL 7', 'HARGA BARANG', 'Harga barang sebagaimana tercantum dalam Lampiran  V  Perjanjian ini.', 1, '2024-03-08 06:26:53', '2024-03-08 07:21:38'),
(8, 'PASAL 8', 'JAMINAN PELAKSANAAN', '(1)Barang yang telah diterima dari PIHAK KEDUA di gudang milik PIHAK KESATU di Karawang diperlakukan sebagai penerimaan sementara sampai dengan prosedur pemeriksaan barang di PIHAK KESATU selesai dilaksanakan, tanpa mengurangi hak PIHAK KESATU untuk mempergunakan barang tersebut dan masih berada dibawah tanggungjawab PIHAK KEDUA apabila ditemukan  kerusakan  dan/atau ketidaksesuaian spesifikasinya.\r\n(2)Selanjutnya terhadap barang yang telah diterima di gudang milik PIHAK KESATU tersebut pada ayat (1) Pasal ini akan dilakukan pemeriksaan oleh PIHAK KESATU sesuai dengan prosedur pemeriksaan yang berlaku di PIHAK KESATU.\r\n(3)Apabila barang yang oleh PIHAK KESATU dinyatakan tidak baik atau tidak sesuai dengan spesifikasi teknis sebagaimana dimaksud Pasal 4 Perjanjian ini, maka PIHAK KEDUA harus segera mengambil barang tersebut dalam waktu selambat-lambatnya 7 (tujuh) hari kalender setelah pemberitahuan oleh PIHAK KESATU dan PIHAK KEDUA berkewajiban untuk menggantinya dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender sejak tanggal pemberitahuan oleh PIHAK KESATU atau dikembalikan pembayarannya oleh PIHAK KEDUA apabila terjadi ketidaksesuaian dengan Jaminan Mutu Barang sebagaimana Pasal 12.\r\n(4)Barang pengganti seperti yang dimaksud ayat (3) Pasal ini harus diserahkan dalam keadaan lengkap, baik dan sesuai spesifikasi teknis sebagaimana dimaksud dalam Pasal 4 Perjanjian ini yang mana terhadap barang pengganti tersebut diberlakukan juga pemeriksaan seperti yang dimaksud ayat (2) Pasal ini.\r\n(5)Barang yang oleh PIHAK KESATU dinyatakan baik dan sesuai dengan spesifikasi teknis sebagaimana dimaksud Pasal 4 Perjanjian ini atau persyaratan yang ditetapkan PIHAK KESATU dibuatkan Surat Penerimaan Barang (SPB) oleh Para Pihak. PIHAK KEDUA tetap harus bertanggungjawab terhadap mutu barang  sebagaimana dimaksud Pasal 12 Perjanjian ini.\r\n(6)Apabila PIHAK KEDUA melanggar ketentuan ayat (3) dan ayat (4) Pasal ini, maka PIHAK KESATU secara sepihak berhak membatalkan Surat Order Pembelian (SOP) dan/atau mengakhiri Perjanjian ini tanpa adanya tuntutan dari PIHAK KEDUA maupun pihak ketiga lainnya atas pelaksanaan Perjanjian ini serta PIHAK KESATU berhak mengalihkan pelaksanaan Perjanjian ini pada pihak lain.\r\n(7)Akibat dari terjadinya pelanggaran sebagaimana dimaksud ayat (6) Pasal ini, maka Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.', 1, '2024-03-08 06:26:53', '2024-03-08 07:21:40'),
(9, 'PASAL 9', 'PENERIMAAN DAN PEMERIKSAAN BARANG', 'Pembayaran dari PIHAK KESATU kepada PIHAK KEDUA dilakukan sebagaimana tercantum dalam Lampiran VI Perjanjian ini.', 1, '2024-03-08 06:26:53', '2024-03-08 07:21:42'),
(10, 'PASAL 10', 'PENYERAHAN PELAKSANAAN PEKERJAAN KEPADA PIHAK KETI', '(1)PIHAK KEDUA tidak diperbolehkan untuk mengalihkan pelaksanaan pekerjaan sebagaimana dimaksud Pasal 3 Perjanjian ini, baik sebagian maupun keseluruhannya kepada pihak ketiga.\r\n(2)PIHAK KEDUA dapat mengalihkan pelaksanaan pekerjaan baik sebagian maupun keseluruhan kepada pihak ketiga yang disebabkan oleh suatu hal tertentu (PIHAK KEDUA dinyatakan pailit) dan/atau keadaan memaksa sebagaimana dimaksud Pasal 15 Perjanjian ini, setelah mendapatkan persetujuan tertulis dari PIHAK KESATU.\r\n(3)Apabila PIHAK KEDUA telah mendapatkan persetujuan dari PIHAK KESATU, maka :\r\na.PIHAK KEDUA bertanggungjawab penuh terhadap mutu Pekerjaan sebagaimana Perjanjian ini.\r\nb.PIHAK KEDUA bertanggungjawab penuh dan akan memberikan ganti rugi kepada PIHAK KESATU apabila Pekerjaan yang dialihkan kepada pihak ketiga mengalami kegagalan, kerusakan yang dapat merugikan PIHAK KESATU.\r\nc.PIHAK KEDUA harus mengawasi Pekerjaan pihak ketiga atas Pekerjaan yang dialihkan tersebut dan melaporkan kepada PIHAK KESATU.\r\nd.PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan/gugatan dan klaim dari pihak ketiga manapun termasuk namun tidak terbatas dari pihak ketiga sehubungan dengan pelaksanaan Pekerjaan dalam Perjanjian ini.\r\n(4)Apabila ketentuan Pasal ini dilanggar oleh PIHAK KEDUA, maka PIHAK KESATU secara sepihak berhak membatalkan dan/atau mengakhiri Perjanjian ini tanpa adanya tuntutan apapun dari PIHAK KEDUA, dan PIHAK KESATU berhak memberikan pelaksanaan pekerjaan tersebut kepada pihak lain serta apabila ada Jaminan Pelaksanaan (Performance Bond) maka Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.', 1, '2024-03-08 06:29:46', '2024-03-08 07:21:46'),
(11, 'PASAL 11', 'PESANAN TAMBAH KURANG', '(1)PIHAK KESATU setiap saat dapat mengubah lingkup pelaksanaan Perjanjian seperti penambahan atau pengurangan pesanan barang.\r\n(2)Jika terdapat perubahan lingkup pelaksanaan sebagaimana dimaksud ayat (1) yang mengakibatkan pada penambahan atau pengurangan harga dan/atau perubahan jadwal penyerahan barang pada Surat Order Pembelian (SOP), maka akan dilakukan penyesuaian harga  dan/atau jadwal penyerahan barang pada Surat Order Pembelian (SOP), yang akan dituangkan dalam suatu surat perubahan Surat Order Pembelian (SOP) dan merupakan bagian yang tidak terpisahkan dari Perjanjian ini.\r\n(3)Harga satuan pesanan tambah kurang dalam Surat Order Pembelian (SOP) tidak boleh melebihi dari harga satuan  yang telah disepakati sebelumnya sebagaimana tercantum dalam dimaksud Pasal 7 Perjanjian ini.\r\n(4)Pesanan tambah kurang baru dapat dilaksanakan oleh PIHAK KEDUA setelah  PIHAK KEDUA menerima Surat Pemberitahuan dari PIHAK KESATU mengenai perubahan pesanan tersebut.\r\n', 1, '2024-03-08 06:29:46', '2024-03-08 07:21:48'),
(12, 'PASAL 12', 'JAMINAN MUTU BARANG', '(1)PIHAK KEDUA memberikan jaminan mutu (garansi) atas barang bahwa barang yang dijual dan diserahkan kepada PIHAK KESATU adalah 100% (seratus persen) baru dan sesuai dengan ketentuan-ketentuan dan syarat-syarat yang ditetapkan dalam Perjanjian ini beserta Lampirannya, karena itu PIHAK KEDUA bertanggung jawab atas segala ketidaksesuaian mutu atas barang termasuk tetapi tidak terbatas cacat tersembunyi ataupun kekurang sempurnaan dalam proses pembuatannya.\r\n(2)Masa Jaminan Mutu (garansi) atas barang menurut Perjanjian ini adalah selama 12 (dua belas) bulan setelah keluarnya Surat Penerimaan Barang (SPB) dari Gudang PIHAK KESATU.\r\n(3)Jaminan ini tidak berlaku bilamana dapat dibuktikan oleh PIHAK KEDUA bahwa ketidaksesuaian mutu atas barang dimaksud Pasal ini disebabkan oleh karena kesalahan didalam pemakaian oleh PIHAK KESATU, namun yang terbukti bukan karena kesalahan dalam proses pembuatan ataupun juga karena kualitas bahan yang digunakan, hal mana harus dibuktikan oleh PIHAK KEDUA dan dapat meyakinkan PIHAK KESATU.\r\n(4)Dalam hal terjadi ketidaksesuaian mutu atas barang sebagaimana dimaksud Pasal ini maka PIHAK KESATU akan memberitahukan secara tertulis dalam jangka waktu selambat-lambatnya 7 (tujuh) hari kalender setelah ketidaksesuaian mutu atas barang tersebut ditemukan, PIHAK KEDUA berkewajiban untuk memperbaiki dan/atau menggantikannya dengan barang yang baru dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender terhitung sejak tanggal pemberitahuan dari PIHAK KESATU, kecuali apabila PIHAK KEDUA dapat membuktikan bahwa ketidaksesuaian mutu atas barang tersebut adalah terjadi karena sebab dimaksud ayat (3) Pasal ini.\r\n(5)Segala ongkos, biaya-biaya serta pengeluaran lain yang timbul karena penggantian dan/atau perbaikan barang tersebut menjadi tanggung jawab PIHAK KEDUA.', 1, '2024-03-08 06:38:51', '2024-03-08 07:21:51'),
(13, 'PASAL 13', 'JAMINAN HUKUM ATAS BARANG', '(1)PIHAK KEDUA menjamin bahwa barang yang diserahkan kepada PIHAK KESATU tidak diperoleh dari hal-hal yang bertentangan dengan hukum.\r\n(2)PIHAK KEDUA menjamin bahwa barang yang diserahkan berdasarkan Perjanjian ini tidak melanggar Hak Atas Kekayaan Intelektual (HAKI) atau hak lain yang dimiliki pihak ketiga.\r\n(3)Jika terjadi klaim atau tuntutan lainnya sehubungan dengan hal tersebut pada ayat (1) dan ayat (2) Pasal ini, PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan apapun dan dimanapun yang mungkin timbul serta PIHAK KEDUA dengan ini menyatakan akan mengambil segala tindakan hukum yang diperlukan termasuk mewakili didepan Pengadilan.\r\n(4)Apabila klaim atau tuntutan pihak ketiga sebagaimana dimaksud Pasal ini dikabulkan oleh Pengadilan atau oleh Badan Hukum apapun, maka PIHAK KEDUA menjamin bahwa barang tersebut tetap dapat dipergunakan dan menjadi milik PIHAK KESATU.\r\n', 1, '2024-03-08 06:38:51', '2024-03-08 07:21:53'),
(14, 'PASAL 14', 'SANKSI', '(1)Apabila jadwal penyerahan barang sebagaimana dimaksud Pasal 5 Perjanjian ini terlampaui maka PIHAK KEDUA akan dikenakan sanksi berupa denda keterlambatan sebesar 1‰ (satu permil) setiap hari kalender keterlambatan dari harga barang sebagainana dimaksud Pasal 7 Perjanjian ini dengan batas maksimum denda keterlambatan sebesar 5% (lima persen) dari total harga barang tersebut tidak termasuk Pajak Pertambahan Nilai (PPN), yang dapat dipotong secara sekaligus dari tagihan PIHAK KEDUA yang belum dibayar PIHAK KESATU.\r\n(2)Apabila denda keterlambatan sudah mencapai batas maksimum sebagaimana dimaksud dalam ayat (1) Pasal ini atau waktu keterlambatan sudah mencapai 50 (lima puluh) hari kalender, maka PIHAK KEDUA dipandang tidak mampu untuk menyelesaikan Perjanjian ini, sehingga PIHAK KESATU berhak secara sepihak untuk memutuskan/mengakhiri Perjanjian ini serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.\r\n(3)Segala kerugian nyata yang disebabkan oleh keterlambatan seperti yang dimaksud Pasal ini akan dibebankan kepada PIHAK KEDUA, kerugian tersebut termasuk tetapi tidak terbatas denda pihak ketiga terhadap PIHAK KESATU dan biaya-biaya lain yang timbul.\r\n(4)Segala kerugian nyata yang diderita PIHAK KESATU akibat ketidak sesuaian mutu atas barang sebagaimana dimaksud Pasal 12 Perjanjian ini, dan/atau kesalahan PIHAK KEDUA, termasuk tetapi tidak terbatas pada denda pihak ketiga terhadap PIHAK KESATU akan dibebankan kepada PIHAK KEDUA.\r\n(5)Apabila ternyata PIHAK KEDUA tidak dapat memenuhi ketentuan-ketentuan Perjanjian ini atau menurut pertimbangan PIHAK KESATU bahwa PIHAK KEDUA dipandang tidak mampu memenuhi ketentuan-ketentuan dalam Perjanjian ini, maka PIHAK KESATU secara sepihak berhak memutuskan/mengakhiri Perjanjian ini. Hal yang sama dapat pula dilakukan apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.\r\n(6)Ketentuan sanksi sebagaimana dimaksud Pasal ini tidak berlaku apabila :\r\na.Keterlambatan seperti yang dimaksud Pasal ini disebabkan karena perintah secara tertulis dari PIHAK KESATU kepada PIHAK KEDUA untuk menunda atau menghentikan sementara waktu pelaksanaan penyerahan barang seperti yang dimaksud Pasal 5 Perjanjian ini.\r\nb.PIHAK KEDUA dapat membuktikan dan dapat meyakinkan PIHAK KESATU bahwa segala ketidak sesuaian mutu atas barang seperti yang dimaksud Pasal 12 Perjanjian ini adalah di luar kesalahan PIHAK KEDUA.\r\n', 1, '2024-03-08 06:38:51', '2024-03-08 07:21:55'),
(15, 'PASAL 15', 'KEADAAN MEMAKSA', '(1)Yang dimaksud dengan Keadaan Memaksa adalah keadaan-keadaan yang disebabkan oleh kejadian-kejadian di luar kesalahan atau kekuasaan dari para pihak yang merintangi atau menghalangi pihak tersebut dalam menjalankan kewajibannya memenuhi Perjanjian ini, seperti :\r\na.Gempa bumi besar, angin topan, banjir besar, kebakaran besar, tanah longsor dan wabah penyakit.\r\nb.Pemogokan umum, huru-hara, sabotase, pemberontakan dan Kebijaksanaan Pemerintah di Bidang Moneter.\r\nc.Kejadian-kejadian lain di luar kekuasaan atau kemampuan dari para pihak.\r\n(2)Dalam hal Keadaan Memaksa yang dimaksud ayat (1) Pasal ini terjadi, maka pihak yang terkena Keadaan Memaksa wajib memberitahukan secara tertulis kepada pihak lainnya dalam jangka waktu 7 (tujuh) hari kalender dari sejak terjadinya Keadaan Memaksa dan diterangkan secara resmi oleh Pejabat yang berwenang mengeluarkannya.\r\n(3)Kelalaian atau keterlambatan pihak yang terkena Keadaan Memaksa dalam menyampaikan pemberitahuannya sebagaimana dimaksud ayat (2) Pasal ini, mengakibatkan tidak diakuinya peristiwa sebagaimana dimaksud ayat (1) Pasal ini sebagai peristiwa Keadaan Memaksa oleh pihak lainnya.\r\n(4)Kejadian-kejadian dimaksud dalam ayat (1) Pasal ini dapat diperhitungkan sebagai perpanjangan waktu kewajiban yang harus dilaksanakan oleh pihak yang terkena Keadaan Memaksa apabila ketentuan dalam ayat (2) Pasal ini dipenuhi, dimana perpanjangan waktu tersebut akan dimusyawarahkan lebih lanjut oleh kedua belah pihak yang syarat-syarat dan ketentuan-ketentuan disetujui bersama yang dituangkan dalam suatu Addendum.\r\n(5)Semua kerugian dan biaya-biaya yang diderita oleh salah satu pihak sebagai akibat Keadaan Memaksa bukan merupakan tanggung jawab pihak lainnya.\r\n', 1, '2024-03-08 06:38:51', '2024-03-08 07:22:02'),
(16, 'PASAL 16', 'PEMBATALAN PERJANJIAN', '(1)PIHAK KESATU berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi :\r\na.Apabila PIHAK KEDUA terbukti tidak dapat menyelenggarakan Perjanjian yang dimaksud pada Pasal 4, 5 dan Pasal 21 Perjanjian ini atau dipandang oleh PIHAK KESATU bahwa PIHAK KEDUA tidak mampu melaksanakan Perjanjian dimaksud Pasal 3 Perjanjian ini.\r\nb.Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 8 ayat (6) Perjanjian ini.\r\nc.Apabila PIHAK KEDUA terbukti melanggar ketentuan Pasal 10 ayat (2) dan (3) Perjanjian ini.\r\nd.Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 14 ayat (2) Perjanjian ini.\r\ne.Apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang.\r\n(2)Untuk hal ihwal pembatalan Perjanjian dimaksud ayat (1) Pasal ini, Para Pihak dengan ini menyatakan sepakat dan berjanji untuk mengesampingkan berlakunya ketentuan Pasal 1266 dan Pasal 1267 Undang-undang Hukum Perdata terhadap Perjanjian ini, sehingga pembatalan Perjanjian ini dapat dilakukan secara sah cukup dengan surat pemberitahuan dari PIHAK KESATU kepada PIHAK KEDUA tanpa menunggu adanya keputusan dari Hakim serta dengan ini PIHAK KEDUA menyatakan melepaskan hak-hak yang timbul dari padanya apabila ada.\r\n(3)Dalam hal Perjanjian ini dibatalkan, maka Para Pihak secara bersama-sama mengadakan inventarisasi terhadap hak dan kewajiban yang ada dan apabila terdapat kekurangan atau kelebihan pembayaran oleh PIHAK KESATU, maka akan diadakan penambahan pembayaran oleh PIHAK KESATU atau pengembalian pembayaran oleh PIHAK KEDUA.\r\n(4)Dalam hal Perjanjian ini dibatalkan, maka PIHAK KEDUA dengan ini berjanji dan menyatakan membebaskan PIHAK KESATU dari segala tuntutan hukum, termasuk tuntutan dari pihak ketiga serta ganti rugi berupa apapun dan dari manapun karena batalnya Perjanjian ini, oleh karena itu sepenuhnya menjadi tanggung jawab PIHAK KEDUA.', 1, '2024-03-08 06:38:51', '2024-03-08 07:26:08'),
(17, 'PASAL 17', 'PENYELESAIAN PERSELISIHAN', '(1)Apabila dikemudian hari terjadi perselisihan dalam penafsiran dan atau pelaksanaan ketentuan-ketentuan dari Perjanjian ini dan atau hal-hal lainnya maka Para Pihak telah sepakat dan berjanji untuk terlebih dahulu menyelesaikan secara musyawarah untuk mencapai mufakat.\r\n(2)Bilamana cara musyawarah tersebut ayat (1) Pasal ini tidak dicapai kata sepakat dalam penyelesaian perselisihan, maka Para Pihak sepakat dan berjanji untuk menyelesaikan seluruh sengketa yang timbul dari Perjanjian ini kepada Badan Arbitrase Nasional Indonesia (BANI), untuk diselesaikan pada tingkat pertama dan terakhir menurut peraturan dan prosedur BANI.\r\nArbitrase akan diselesaikan oleh 3 (tiga) orang Arbiter yang ditunjuk sebagai berikut :\r\na.Masing-masing dari Para Pihak harus menunjuk 1 (satu) Arbiter dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal suatu permintaan untuk Arbitrase telah dikeluarkan oleh pihak yang meminta atau para pihak lain telah bersama-sama setuju membawa perselisihan kepada Arbitrase dan kedua Arbiter yang ditunjuk secara bersama-sama akan menunjuk Arbiter ketiga yang akan menjadi Ketua Arbitrase.\r\nb.Apabila salah satu dari para pihak gagal menunjuk Arbiternya dalam jangka waktu sebagaimana dinyatakan di atas, Arbiter yang telah ditunjuk akan duduk sendiri sebagai Arbitrase dan memberikan Keputusan.\r\nc.Namun apabila kedua Arbiter gagal menunjuk Arbiter ketiga dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal penunjukan kedua Arbiter, maka Ketua BANI atau Pejabat BANI yang berwenang akan menunjuk Arbiter ketiga sebagai Ketua Arbiter atas permintaan salah satu pihak.\r\n(3)Para pihak harus menanggung biaya Arbitrase secara sama rata dan proses Arbitrase harus dilangsungkan di Jakarta.\r\n(4)Kecuali dalam ayat (2) sub b. Pasal ini, Keputusan Badan Arbitrase diambil berdasarkan suara terbanyak dan bersifat mengikat kedua belah pihak terhadap para pihak.\r\n(5)Para pihak telah sepakat dan berjanji untuk secara tegas menentukan tidak ada banding atau penghentian pelaksanaan yang diajukan ke Pengadilan atas Keputusan Badan Arbitrase dan para pihak tidak akan menolak atau menentang pelaksanaan keputusan yang dilakukan oleh pihak untuk keuntungan siapa keputusan Badan Arbitrase telah diberikan.\r\n(6)Tiada satu pihak berhak untuk memulai atau melakukan tindakan di Pengadilan terhadap segala masalah dalam sengketa sampai dengan masalah tersebut telah diputuskan sebagaimana diatur di sini, kecuali untuk pelaksanaan keputusan Badan Arbitrase.\r\n(7)Selama proses Arbitrase dan sampai Arbitrase memberikan keputusannya, para pihak setuju untuk terus melaksanakan semua kewajibannya masing-masing berdasarkan Perjanjian ini tanpa berprasangka atau menduga atas putusan akhir yang diambil oleh para Arbiter tersebut.\r\n(8)Para pihak setuju memberlakukan penunjukan tidak akan berakhir pada tanggal setelah 6 (enam) bulan kalender sejak tanggal penunjukannya dan mandat kepada Arbitrase (wasit-wasit) sebagaimana yang ditetapkan sesuai dengan keputusan ini, akan tetap berlangsung sampai keputusan telah diambil oleh Badan Arbitrase.\r\n(9)Keputusan Badan Arbitrase dapat dilaksanakan di setiap Pengadilan dimanapun yang mempunyai yurisdiksi yang berwenang terhadap masing-masing para pihak atau harta kekayaannya.', 1, '2024-03-08 06:38:51', '2024-03-08 07:26:11'),
(18, 'PASAL 18', 'KETENTUAN MENJAGA RAHASIA', '(1)Para Pihak sepakat melakukan usaha-usaha mereka yang terbaik untuk menjaga kerahasiaan Informasi sehubungan dengan Perjanjian ini dan  Para Pihak harus memastikan direktur-direktur, pegawai-pegawai, agen-agen atau pembantu-pembantu mereka tidak akan mengungkapkan informasi, data, dokumentasi dan pengetahuan kepada Pihak Ketiga tanpa persetujuan tertulis dari pihak yang lain, tidak juga akan menerbitkan informasi, data, dokumentasi dan pengetahuan dalam bentuk cetakan, kaset, disket, disk atau bentuk-bentuk lain, kecuali sepanjang tindakan dilakukan sebagai laporan kepada instansi pemerintah terkait sebagaimana diperlukan oleh undang-undang.\r\n(2)Pengecualian Informasi Ketentuan tidak berlaku dalam hal Informasi telah menjadi milik umum atau dengan lewatnya waktu 10 (sepuluh) tahun sejak penandatanganan Perjanjian ini.', 1, '2024-03-08 06:44:14', '2024-03-08 07:26:14'),
(19, 'PASAL 19', 'PERLINDUNGAN DATA PRIBADI', 'Kewajiban Para Pihak dalam upaya Pelindungan Data Pribadi:\r\n(1)Memproses Data Pribadi sesuai Undang-Undang Perlindungan Data Pribadi dan ketentuan dalam Peraturan Perundang-undangan lainnya.\r\n(2)Hanya memproses Data Pribadi apabila dan hanya sejauh diperlukan agar dapat melaksanakan kewajiban berdasarkan Perjanjian; \r\n(3)Tidak mengungkapkan Data Pribadi kepada pihak ketiga mana pun selain:\r\na.Karyawan, direksi, afiliasi berdasarkan kebutuhan (need-to know) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini; \r\nb.Subkontraktor atau penasehat professional yang diizinkan secara tertulis oleh Para Pihak untuk memproses Data Pribadi berdasarkan kebutuhan (need-to know basis) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini; atau \r\nc.Sejauh diperlukan oleh peraturan perundang-undangan yang berlaku, namun tetap memperhatikan dan mematuhi Undang-Undang Perlindungan Data. Dalam hal tersebut, Pihak yang berkepentingan harus memberikan pemberitahuan tertulis kepada Pihak lainnya untuk mengungkapkan Data Pribadi (sejauh diizinkan oleh peraturan perundang-undangan yang berlaku) segera mungkin setelah mengetahui persyaratan tersebut.\r\n(4)Memastikan bahwa personilnya yang memproses Data Pribadi melaksanakan hal tersebut dan tetap patuh terhadap kewajiban kerahasiaan; dan\r\n(5)Melaksanakan dan mempertahankan tindakan atau langkah administratif, teknis dan organisasi yang cukup: \r\na.Untuk menjaga keamanan Data Pribadi; dan \r\nb.Untuk mencegah penghapusan tidak sah atau tidak disengaja, perubahan tidak sah, menyalin, mengakses atau menggunakan, pemalsuan, pencurian, kehilangan atau kesalahan teknis sehubungan dengan Data Pribadi.\r\n(6)PIHAK KESATU maupun PIHAK KEDUA bertanggung jawab atas kerugian terhadap pelanggaran ketentuan terkait Data Pribadi yang diakibatkan oleh kelalaian personilnya serta akan bertanggung jawab penuh, termasuk namun tidak terbatas pada segala klaim, tuntutan, gugatan, sengketa, dan/atau ganti kerugian yang mungkin timbul dari pelanggaran ketentuan terkait Data Pribadi.', 1, '2024-03-08 06:44:14', '2024-03-08 07:26:16'),
(20, 'PASAL 20', 'HUKUM YANG BERLAKU', 'Perjanjian   ini   tunduk   dan   berada   di   bawah ketentuan hukum Republik Indonesia.', 1, '2024-03-08 06:44:14', '2024-03-08 07:26:18'),
(21, 'PASAL 21', 'LARANGAN PEMBERIAN HADIAH DAN KOMISI', '(1)PIHAK KEDUA dilarang untuk menerima penawaran atau menyetujui pemberian hadiah, komisi, potongan atau bentuk-bentuk lain yang sejenis dari Direksi, staff/karyawan dari PIHAK KESATU untuk tujuan ditandatanganinya dan/atau pelaksanaan Perjanjian ini.\r\n(2)Pelanggaran terhadap ayat 1 Pasal ini oleh PIHAK KEDUA atau karyawannya atau pihak lain yang bekerja untuk PIHAK KEDUA dapat mengakibatkan pembatalan Perjanjian ini oleh PIHAK KESATU, dan biaya yang timbul dari pembatalan tersebut akan menjadi tanggung jawab PIHAK KEDUA, dan PIHAK KEDUA akan dieliminasi sebagai mitra bisnis PIHAK KESATU.\r\n(3)Pelanggaran dari setiap ketentuan dalam Pasal ini akan mengakibatkan gugatan pidana terhadap PIHAK KEDUA. Dalam hal terjadi penindaklanjutan atas adanya tindakan penerimaan komisi atau hadiah yang berpotensi merugikan PIHAK KESATU, semua biaya, ongkos dan kerugian yang timbul akan menjadi tanggung jawab PIHAK KEDUA. ', 1, '2024-03-08 06:44:14', '2024-03-08 07:26:20'),
(22, 'PASAL 22', 'JAMINAN PELAKSANAAN', '(1)PIHAK KEDUA berkewajiban menyerahkan kepada PIHAK KESATU Jaminan Bank untuk Jaminan Pelaksanaan (Performance Bond) dari Bank BUMN/BUMD sebesar 5% (lima persen) dari total harga Barang secara keseluruhan sebagaimana dimaksud Pasal 7 Perjanjian ini.\r\n(2)Jaminan Pelaksanaan sebagaimana dimaksud ayat (1) Pasal ini harus mempunyai masa berlaku sampai dengan pelaksanaan Perjanjian selesai secara 100% (seratus persen) yang dinyatakan dengan Surat Penerimaan Barang (SPB).\r\n(3)Apabila Jaminan Pelaksanaan dimaksud ayat (1) Pasal ini akan habis masa berlakunya sementara pelaksanaan Perjanjian belum selesai, maka PIHAK KEDUA berkewajiban untuk memperpanjang masa berlaku Jaminan Pelaksanaan tersebut selambat-lambatnya dalam waktu 7 (tujuh) hari kalender sebelum habis masa berlakunya Jaminan Pelaksanaan tersebut.\r\n(4)Apabila PIHAK KEDUA baik lalai ataupun sengaja tidak menyerahkan Jaminan Pelaksanaan yang telah diperpanjang masa berlakunya dalam waktu paling lambat 5 (lima) hari kalender sebelum Jaminan Pelaksanaan yang dimaksud dalam ayat (1) Pasal ini jatuh tempo, maka PIHAK KESATU berhak secara sepihak tanpa perlu adanya pemberitahuan terlebih dahulu kepada PIHAK KEDUA untuk mencairkan Jaminan Pelaksanaan tersebut pada saat berakhirnya Jaminan Pelaksanaan dan PIHAK KESATU berhak pula untuk menahan pembayarannya serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.\r\n(5)Apabila PIHAK KEDUA lalai memenuhi kewajibannya sesuai dengan syarat-syarat dan ketentuan-ketentuan dalam Perjanjian ini dan/atau Perjanjian ini dibatalkan karena kesalahan PIHAK KEDUA, maka Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.\r\n(6)Jaminan Pelaksanaan sebagaimana dimaksud ayat (1) dan ayat (2) Pasal ini akan dikembalikan oleh PIHAK KESATU kepada PIHAK KEDUA apabila pelaksanaan Perjanjian ini telah selesai secara 100% (seratus persen) yang dinyatakan dengan Surat Penerimaan Barang (SPB).', 1, '2024-03-08 06:44:14', '2024-03-08 07:26:25'),
(23, 'PASAL 23', 'TANGGAL BERLAKUNYA PERJANJIAN', 'Perjanjian ini berlaku efektif terhitung sejak ditandatanganinya Perjanjian ini oleh wakil Para Pihak yang berwenang.', 1, '2024-03-08 06:44:14', '2024-03-08 07:26:29'),
(24, 'PASAL 24', 'LAMPIRAN - LAMPIRAN', '(1)	Lampiran I 	:  Dokumen-Dokumen Pengadaan\r\n(2)	Lampiran II	:  Lingkup Perjanjian\r\n(3)	Lampiran III	:  Spesifikasi Teknis\r\n(4)	Lampiran IV	:  Jadwal Penyerahan Barang\r\n(5)	Lampiran V	:  Harga Barang\r\n(6)	Lampiran VI	:  Pembayaran\r\n(7)	Lampiran VII	:  Alamat Surat Menyurat', 1, '2024-03-08 06:45:31', '2024-03-08 07:26:31'),
(25, 'PASAL 25', 'LAIN - LAIN', '(1)Hal-hal yang belum diatur dan perubahan-perubahan dari Perjanjian ini, akan diselesaikan melalui kesepakatan atau perundingan kedua belah pihak dan yang akan dituangkan dalam suatu Addendum Perjanjian yang ditandatangani oleh kedua belah pihak serta merupakan bagian yang tidak dapat dipisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.\r\n(2)Segala ketentuan-ketentuan dan syarat-syarat dalam Perjanjian ini berlaku serta mengikat bagi pihak-pihak yang menandatangani, pengganti-penggantinya dan mereka yang memperoleh keuntungan dari padanya.\r\n(3)Lampiran Perjanjian merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.\r\nDemikian Perjanjian ini dibuat dalam 2 (dua) rangkap ASLI masing-masing sama bunyi dan bermeterai cukup serta mempunyai kekuatan hukum yang sama setelah ditandatangani dan dibubuhi cap perusahaan kedua belah pihak.', 1, '2024-03-08 06:45:31', '2024-03-08 07:26:32'),
(26, 'PASAL 1', 'DEFINISI-DEFINISI', '(1)Perjanjian adalah Perjanjian ini yang dibuat dan ditandatangani antara Para Pihak, termasuk seluruh lampirannya dan setiap perubahan-perubahannya.\r\n(2)Barang adalah Pengadaan barang yang harus diadakan dan dipasok oleh PIHAK KEDUA.\r\n(3)Spesifikasi Teknis adalah Spesifikasi Teknis barang yang telah disepakati bersama oleh para pihak sebagaimana dimaksud dalam Lampiran III Perjanjian ini.\r\n(4)Bulan dan Hari adalah bulan dan hari terkait yang tercantum dalam kalender Masehi.\r\n(5)Tanggal Berlakunya Perjanjian adalah tanggal dimana semua ketentuan yang terdapat pada Pasal 22 terpenuhi.\r\n(6)Surat Penerimaan Barang (SPB) adalah pernyataan tertulis bertanggal dan diterbitkan oleh PIHAK KESATU yang menyatakan bahwa barang telah diserahkan dan diterima oleh PIHAK KESATU sesuai dengan Perjanjian.\r\n(7)Jaminan Mutu adalah kewajiban PIHAK KEDUA untuk menjaga kualitas barang selama masa tertentu sebagaimana diatur dalam Perjanjian ini. \r\n', 2, '2024-03-08 07:29:06', NULL),
(29, 'PASAL 2', 'KETENTUAN-KETENTUAN UMUM', '(1)Apabila suatu ketentuan Perjanjian ini atau bagian dari padanya dianggap batal, tidak sah atau tidak dapat diberlakukan berdasarkan peraturan perundang-undangan yang berlaku terhadap mana ketentuan tersebut tunduk, maka ketentuan dimaksud dianggap batal, tidak sah atau tidak dapat diberlakukan dengan cara apapun, tidak berpengaruh pada atau mengurangi berlakunya bagian lain dari ketentuan tersebut atau ketentuan-ketentuan lainnya dari Perjanjian ini.\r\n(2)Kelalaian salah satu Pihak dalam melaksanakan, dan keterlambatan satu Pihak melaksanakan hak berdasarkan Perjanjian ini, tidak berlaku sebagai pembebasan atau pengesampingan dari setiap pelaksanaan keseluruhan atau sebagian dari hak berdasarkan Perjanjian ini tidak mencegah pelaksanaan lain atau pelaksanaan selanjutnya dari hak tersebut.\r\n(3)Perjanjian ini berlaku untuk kepentingan dan mengikat Para Pihak, para pengganti dan para penerima hak yang diijinkan masing-masing Pihak.\r\n', 2, '2024-03-08 07:29:23', NULL),
(30, 'PASAL 3', 'LINGKUP PERJANJIAN', 'Lingkup Perjanjian sebagaimana tercantum pada Lampiran II Perjanjian ini.', 2, '2024-03-08 07:41:32', NULL),
(31, 'PASAL 4', 'SPESIFIKASI TEKNIS', 'Spesifikasi teknis barang sebagaimana tercantum dalam Lampiran III Perjanjian ini.', 2, '2024-03-08 07:41:32', NULL),
(32, 'PASAL 5', 'JADWAL PENYERAHAN BARANG', 'Jadwal penyerahan barang sebagaimana dimaksud dalam Lampiran IV Perjanjian ini.', 2, '2024-03-08 07:41:32', NULL),
(33, 'PASAL 6', 'PERUBAHAN JADWAL PENYERAHAN BARANG', '(1)Jadwal penyerahan barang dimaksud Pasal 5 Perjanjian ini dapat berubah sewaktu-waktu sesuai permintaan PIHAK KESATU, yang mana permintaan tersebut dibuat secara tertulis oleh dan dari PIHAK KESATU kepada PIHAK KEDUA.\r\n(2)Perubahan dimaksud ayat (1) Pasal ini akan dituangkan dalam suatu Addendum Lampiran IV, yang merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.\r\n', 2, '2024-03-08 07:41:32', NULL),
(34, 'PASAL 7', 'HARGA BARANG', 'Harga barang sebagaimana tercantum dalam Lampiran  V  Perjanjian ini.', 2, '2024-03-08 07:41:32', NULL),
(35, 'PASAL 8', 'PENERIMAAN DAN PEMERIKSAAN BARANG', '(1)Barang yang telah diterima dari PIHAK KEDUA di gudang milik PIHAK KESATU di Karawang diperlakukan sebagai penerimaan sementara sampai dengan prosedur pemeriksaan barang di PIHAK KESATU selesai dilaksanakan, tanpa mengurangi hak PIHAK KESATU untuk mempergunakan barang tersebut dan masih berada dibawah tanggungjawab PIHAK KEDUA apabila ditemukan  kerusakan  dan/atau ketidaksesuaian spesifikasinya. \r\n(2)Selanjutnya terhadap barang yang telah diterima di gudang milik PIHAK KESATU di Karawang tersebut pada ayat (1) Pasal ini akan dilakukan pemeriksaan oleh PIHAK KESATU sesuai dengan prosedur pemeriksaan yang berlaku di PIHAK KESATU.\r\n(3)Apabila barang yang oleh PIHAK KESATU dinyatakan tidak baik atau tidak sesuai dengan spesifikasi teknis sebagaimana dimaksud Pasal 4 Perjanjian ini, maka PIHAK KEDUA harus segera mengambil barang tersebut dalam waktu selambat-lambatnya 7 (tujuh) hari kalender setelah pemberitahuan oleh PIHAK KESATU dan PIHAK KEDUA berkewajiban untuk menggantinya dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender sejak tanggal pemberitahuan oleh PIHAK KESATU atau dikembalikan pembayarannya oleh PIHAK KEDUA apabila terjadi ketidaksesuaian dengan Jaminan Mutu Barang sebagaimana Pasal 12.\r\n(4)Barang pengganti seperti yang dimaksud ayat (3) Pasal ini harus diserahkan dalam keadaan lengkap, baik dan sesuai spesifikasi teknis sebagaimana dimaksud dalam Pasal 4 Perjanjian ini yang mana terhadap barang pengganti tersebut diberlakukan juga pemeriksaan seperti yang dimaksud ayat (2) Pasal ini.\r\n(5)Barang yang oleh PIHAK KESATU dinyatakan baik dan sesuai dengan spesifikasi teknis sebagaimana dimaksud Pasal 4 Perjanjian ini atau persyaratan yang ditetapkan PIHAK KESATU dibuatkan Surat Penerimaan Barang (SPB) oleh Para Pihak. PIHAK KEDUA tetap harus bertanggungjawab terhadap mutu barang  seperti yang dimaksud Pasal 12 Perjanjian ini.\r\n(6)Apabila PIHAK KEDUA melanggar ketentuan ayat (3) dan ayat (4) Pasal ini, maka PIHAK KESATU secara sepihak berhak membatalkan Surat Order Pembelian (SOP) dan/atau mengakhiri Perjanjian ini tanpa adanya tuntutan dari PIHAK KEDUA maupun pihak ketiga lainnya atas pelaksanaan Perjanjian ini serta PIHAK KESATU berhak mengalihkan pelaksanaan Perjanjian ini pada pihak lain. ', 2, '2024-03-08 07:41:32', NULL),
(36, 'PASAL 9', 'PEMBAYARAN', 'Pembayaran dari PIHAK KESATU kepada PIHAK KEDUA dilakukan sebagaimana tercantum dalam Lampiran VI Perjanjian ini.', 2, '2024-03-08 07:47:13', NULL),
(37, 'PASAL 10', 'PENYERAHAN PELAKSANAAN PEKERJAAN KEPADA PIHAK KETI', '(1)PIHAK KEDUA tidak diperbolehkan untuk mengalihkan pelaksanaan pekerjaan sebagaimana dimaksud Pasal 3 Perjanjian ini, baik sebagian maupun keseluruhannya kepada pihak ketiga.\r\n(2)PIHAK KEDUA dapat mengalihkan pelaksanaan pekerjaan baik sebagian maupun keseluruhan kepada pihak ketiga yang disebabkan oleh suatu hal tertentu dan/atau keadaan memaksa sebagaimana dimaksud Pasal 15 Perjanjian ini, setelah mendapatkan persetujuan tertulis dari PIHAK KESATU.\r\n(3)Apabila PIHAK KEDUA telah mendapatkan persetujuan dari PIHAK KESATU, maka :\r\na.PIHAK KEDUA bertanggungjawab penuh terhadap mutu Pekerjaan sebagaimana Perjanjian ini.\r\nb.PIHAK KEDUA bertanggungjawab penuh dan akan memberikan ganti rugi kepada PIHAK KESATU apabila Pekerjaan yang dialihkan kepada pihak ketiga mengalami kegagalan, kerusakan yang dapat merugikan PIHAK KESATU.\r\nc.PIHAK KEDUA harus mengawasi Pekerjaan pihak ketiga atas Pekerjaan yang dialihkan tersebut dan melaporkan kepada PIHAK KESATU.\r\nd.PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan/gugatan dan klaim dari pihak ketiga manapun termasuk namun tidak terbatas dari pihak ketiga sehubungan dengan pelaksanaan Pekerjaan dalam Perjanjian ini.\r\n(4)Apabila ketentuan Pasal ini dilanggar oleh PIHAK KEDUA, maka PIHAK KESATU secara sepihak berhak membatalkan dan/atau mengakhiri Perjanjian ini tanpa adanya tuntutan apapun dari PIHAK KEDUA, dan PIHAK KESATU berhak memberikan pelaksanaan pekerjaan tersebut kepada pihak lain.', 2, '2024-03-08 07:47:13', NULL),
(38, 'PASAL 11', 'PESANAN TAMBAH KURANG', '(1)PIHAK KESATU setiap saat dapat mengubah lingkup pelaksanaan Perjanjian seperti penambahan atau pengurangan pesanan barang.\r\n(2)Jika terdapat perubahan lingkup pelaksanaan sebagaimana dimaksud ayat (1) yang mengakibatkan pada penambahan atau pengurangan harga dan/atau perubahan jadwal penyerahan barang pada Surat Order Pembelian (SOP), maka akan dilakukan penyesuaian harga  dan/atau jadwal penyerahan barang pada Surat Order Pembelian (SOP), yang akan dituangkan dalam suatu surat perubahan Surat Order Pembelian (SOP) dan merupakan bagian yang tidak terpisahkan dari Perjanjian ini.\r\n(3)Harga satuan pesanan tambah kurang dalam Surat Order Pembelian (SOP) tidak boleh melebihi dari harga satuan  yang telah disepakati sebelumnya sebagaimana tercantum dalam dimaksud Pasal 7 Perjanjian ini.\r\n(4)Pesanan tambah kurang baru dapat dilaksanakan oleh PIHAK KEDUA setelah  PIHAK KEDUA menerima Surat Pemberitahuan dari PIHAK KESATU mengenai perubahan pesanan tersebut.', 2, '2024-03-08 07:47:13', NULL),
(39, 'PASAL 12', 'JAMINAN MUTU BARANG', '(1)PIHAK KEDUA memberikan jaminan mutu (garansi) atas barang bahwa barang yang dijual dan diserahkan kepada PIHAK KESATU adalah 100% (seratus persen) baru dan sesuai dengan ketentuan-ketentuan dan syarat-syarat yang ditetapkan dalam Perjanjian ini beserta Lampirannya, karena itu PIHAK KEDUA bertanggung jawab atas segala ketidaksesuaian mutu atas barang termasuk tetapi tidak terbatas cacat tersembunyi ataupun kekurang sempurnaan dalam proses pembuatannya.\r\n(2)Masa Jaminan Mutu (garansi) atas barang menurut Perjanjian ini adalah selama 12 (dua belas) bulan setelah keluarnya Surat Penerimaan Barang (SPB) dari Gudang PIHAK KESATU.\r\n(3)Jaminan ini tidak berlaku bilamana dapat dibuktikan oleh PIHAK KEDUA bahwa ketidaksesuaian mutu atas barang dimaksud Pasal ini disebabkan oleh karena kesalahan didalam pemakaian oleh PIHAK KESATU, namun yang terbukti bukan karena kesalahan dalam proses pembuatan ataupun juga karena kualitas bahan yang digunakan, hal mana harus dibuktikan oleh PIHAK KEDUA dan dapat meyakinkan PIHAK KESATU.\r\n(4)Dalam hal terjadi ketidaksesuaian mutu atas barang sebagaimana dimaksud Pasal ini maka PIHAK KESATU akan memberitahukan secara tertulis dalam jangka waktu selambat-lambatnya 7 (tujuh) hari kalender setelah ketidaksesuaian mutu atas barang tersebut ditemukan, PIHAK KEDUA berkewajiban untuk memperbaiki dan atau menggantikannya dengan barang yang baru dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender terhitung sejak tanggal pemberitahuan dari PIHAK KESATU, kecuali apabila PIHAK KEDUA dapat membuktikan bahwa ketidaksesuaian mutu atas barang tersebut adalah terjadi karena sebab dimaksud ayat (3) Pasal ini.\r\n(5)Segala ongkos, biaya-biaya serta pengeluaran lain yang timbul karena penggantian dan atau perbaikan barang tersebut menjadi tanggung jawab PIHAK KEDUA.', 2, '2024-03-08 07:47:13', NULL),
(40, 'PASAL 13', 'JAMINAN HUKUM ATAS BARANG', '(1)PIHAK KEDUA menjamin bahwa barang yang diserahkan kepada PIHAK KESATU tidak diperoleh dari hal-hal yang bertentangan dengan hukum.\r\n(2)PIHAK KEDUA menjamin bahwa barang yang diserahkan berdasarkan Perjanjian ini tidak melanggar Hak Atas Kekayaan Intelektual (HAKI) atau hak lain yang dimiliki pihak ketiga.\r\n(3)Jika terjadi klaim atau tuntutan lainnya sehubungan dengan hal tersebut pada ayat (1) dan ayat (2) Pasal ini, PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan apapun dan dimanapun yang mungkin timbul serta PIHAK KEDUA dengan ini menyatakan akan mengambil segala tindakan hukum yang diperlukan termasuk mewakili didepan Pengadilan.\r\n(4)Apabila klaim atau tuntutan pihak ketiga sebagaimana dimaksud Pasal ini dikabulkan oleh Pengadilan atau oleh Badan Hukum apapun, maka PIHAK KEDUA menjamin bahwa barang tersebut tetap dapat dipergunakan dan menjadi milik PIHAK KESATU.', 2, '2024-03-08 07:47:13', NULL),
(41, 'PASAL 14', 'SANKSI', '(1)Apabila jadwal penyerahan barang sebagaimana dimaksud Pasal 5 Perjanjian ini terlampaui maka PIHAK KEDUA akan dikenakan sanksi berupa denda keterlambatan sebesar 1‰ (satu permil) setiap hari kalender keterlambatan dari harga barang sebagaimana dimaksud Pasal 7 Perjanjian ini dengan batas maksimum denda keterlambatan sebesar 5% (lima persen) dari total harga barang tersebut tidak termasuk Pajak Pertambahan Nilai (PPN), yang dapat dipotong secara sekaligus dari tagihan PIHAK KEDUA yang belum dibayar PIHAK KESATU.\n(2)Apabila denda keterlambatan sudah mencapai batas maksimum sebagaimana dimaksud dalam ayat (1) Pasal ini atau waktu keterlambatan sudah mencapai 50 (lima puluh) hari kalender, maka PIHAK KEDUA dipandang tidak mampu untuk menyelesaikan Perjanjian ini, sehingga PIHAK KESATU berhak secara sepihak untuk memutuskan/mengakhiri Perjanjian ini serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.\n(3)Segala kerugian nyata yang disebabkan oleh keterlambatan seperti yang dimaksud Pasal ini akan dibebankan kepada PIHAK KEDUA, kerugian tersebut termasuk tetapi tidak terbatas denda pihak ketiga terhadap PIHAK KESATU dan biaya-biaya lain yang timbul.\n(4)Segala kerugian nyata yang diderita PIHAK KESATU akibat ketidak sesuaian mutu atas barang sebagaimana dimaksud Pasal 12 Perjanjian ini, dan atau kesalahan PIHAK KEDUA, termasuk tetapi tidak terbatas pada denda pihak ketiga terhadap PIHAK KESATU akan dibebankan kepada PIHAK KEDUA.\n(5)Apabila ternyata PIHAK KEDUA tidak dapat memenuhi ketentuan-ketentuan Perjanjian ini atau menurut pertimbangan PIHAK KESATU bahwa PIHAK KEDUA dipandang tidak mampu memenuhi ketentuan-ketentuan dalam Perjanjian ini, maka PIHAK KESATU secara sepihak berhak memutuskan/mengakhiri Perjanjian ini. Hal yang sama dapat pula dilakukan apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang \n(6)Ketentuan sanksi sebagaimana dimaksud Pasal ini tidak berlaku apabila :\na.Keterlambatan seperti yang dimaksud Pasal ini disebabkan karena perintah secara tertulis dari PIHAK KESATU kepada PIHAK KEDUA untuk menunda atau menghentikan sementara waktu pelaksanaan penyerahan barang seperti yang dimaksud Pasal 5 Perjanjian ini.\nb.PIHAK KEDUA dapat membuktikan dan dapat meyakinkan PIHAK KESATU bahwa segala ketidak sesuaian mutu atas barang seperti yang dimaksud Pasal 12 Perjanjian ini adalah di luar kesalahan PIHAK KEDUA', 2, '2024-03-08 07:47:13', '2024-03-08 07:48:16'),
(42, 'PASAL 15', 'KEADAAN MEMAKSA', '(1)Yang dimaksud dengan Keadaan Memaksa adalah keadaan-keadaan yang disebabkan oleh kejadian-kejadian di luar kesalahan atau kekuasaan dari para pihak yang merintangi atau menghalangi pihak tersebut dalam menjalankan kewajibannya memenuhi Perjanjian ini, seperti :\r\na.Gempa bumi besar, angin topan, banjir besar, kebakaran besar, tanah longsor dan wabah penyakit.\r\nb.Pemogokan umum, huru-hara, sabotase, pemberontakan dan Kebijaksanaan Pemerintah di Bidang Moneter.\r\nc.Kejadian-kejadian lain di luar kekuasaan atau kemampuan dari para pihak.\r\n(2)Dalam hal Keadaan Memaksa yang dimaksud ayat (1) Pasal ini terjadi, maka pihak yang terkena Keadaan Memaksa wajib memberitahukan secara tertulis kepada pihak lainnya dalam jangka waktu 7 (tujuh) hari kalender dari sejak terjadinya Keadaan Memaksa dan diterangkan secara resmi oleh Pejabat yang berwenang mengeluarkannya.\r\n(3)Kelalaian atau keterlambatan pihak yang terkena Keadaan Memaksa dalam menyampaikan pemberitahuannya sebagaimana dimaksud ayat (2) Pasal ini, mengakibatkan tidak diakuinya peristiwa sebagaimana dimaksud ayat (1) Pasal ini sebagai peristiwa Keadaan Memaksa oleh pihak lainnya.\r\n(4)Kejadian-kejadian dimaksud dalam ayat (1) Pasal ini dapat diperhitungkan sebagai perpanjangan waktu kewajiban yang harus dilaksanakan oleh pihak yang terkena Keadaan Memaksa apabila ketentuan dalam ayat (2) Pasal ini dipenuhi, dimana perpanjangan waktu tersebut akan dimusyawarahkan lebih lanjut oleh kedua belah pihak yang syarat-syarat dan ketentuan-ketentuan disetujui bersama yang dituangkan dalam suatu Addendum.\r\n(5)Semua kerugian dan biaya-biaya yang diderita oleh salah satu pihak sebagai akibat Keadaan Memaksa bukan merupakan tanggung jawab pihak lainnya.', 2, '2024-03-08 07:55:29', NULL),
(43, 'PASAL 16', 'PEMBATALAN PERJANJIAN', '(1)PIHAK KESATU berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi :\r\na.Apabila PIHAK KEDUA terbukti tidak dapat menyelenggarakan Perjanjian yang dimaksud pada Pasal 4, 5 dan Pasal 8 Perjanjian ini atau dipandang oleh PIHAK KESATU bahwa PIHAK KEDUA tidak mampu melaksanakan Perjanjian dimaksud Pasal 3 Perjanjian ini.\r\nb.Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 8 ayat (6) Perjanjian ini.\r\nc.Apabila PIHAK KEDUA terbukti melanggar ketentuan Pasal 10 ayat (2) dan (3) Perjanjian ini.\r\nd.Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 15 ayat (2) Perjanjian ini.\r\ne.Apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang.\r\n(2)Untuk hal ihwal pembatalan Perjanjian dimaksud ayat (1) Pasal ini, Para Pihak dengan ini menyatakan sepakat dan berjanji untuk mengesampingkan berlakunya ketentuan Pasal 1266 dan Pasal 1267 Undang-undang Hukum Perdata terhadap Perjanjian ini, sehingga pembatalan Perjanjian ini dapat dilakukan secara sah cukup dengan surat pemberitahuan dari PIHAK KESATU kepada PIHAK KEDUA tanpa menunggu adanya keputusan dari Hakim serta dengan ini PIHAK KEDUA menyatakan melepaskan hak-hak yang timbul dari padanya apabila ada.\r\n(3)Dalam hal Perjanjian ini dibatalkan, maka Para Pihak secara bersama-sama mengadakan inventarisasi terhadap hak dan kewajiban yang ada dan apabila terdapat kekurangan atau kelebihan pembayaran oleh PIHAK KESATU, maka akan diadakan penambahan pembayaran oleh PIHAK KESATU atau pengembalian pembayaran oleh PIHAK KEDUA.\r\n(4)Dalam hal Perjanjian ini dibatalkan, maka PIHAK KEDUA dengan ini berjanji dan menyatakan membebaskan PIHAK KESATU dari segala tuntutan hukum, termasuk tuntutan dari pihak ketiga serta ganti rugi berupa apapun dan dari manapun karena batalnya Perjanjian ini, oleh karena itu sepenuhnya menjadi tanggung jawab PIHAK KEDUA.', 2, '2024-03-08 07:55:29', NULL);
INSERT INTO `pasal-kontrak` (`id`, `nama_pasal`, `keterangan_pasal`, `isi_pasal`, `jenis_pasal`, `created_at`, `updated_at`) VALUES
(44, 'PASAL 17', 'PENYELESAIAN PERSELISIHAN', '(1)Apabila dikemudian hari terjadi perselisihan dalam penafsiran dan atau pelaksanaan ketentuan-ketentuan dari Perjanjian ini dan atau hal-hal lainnya maka Para Pihak telah sepakat dan berjanji untuk terlebih dahulu menyelesaikan secara musyawarah untuk mencapai mufakat.\r\n(2)Bilamana cara musyawarah tersebut ayat (1) Pasal ini tidak dicapai kata sepakat dalam penyelesaian perselisihan, maka Para Pihak sepakat dan berjanji untuk menyelesaikan seluruh sengketa yang timbul dari Perjanjian ini kepada Badan Arbitrase Nasional Indonesia (BANI), untuk diselesaikan pada tingkat pertama dan terakhir menurut peraturan dan prosedur BANI.\r\nArbitrase akan diselesaikan oleh 3 (tiga) orang Arbiter yang ditunjuk sebagai berikut :\r\na.Masing-masing dari Para Pihak harus menunjuk 1 (satu) Arbiter dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal suatu permintaan untuk Arbitrase telah dikeluarkan oleh pihak yang meminta atau para pihak lain telah bersama-sama setuju membawa perselisihan kepada Arbitrase dan kedua Arbiter yang ditunjuk secara bersama-sama akan menunjuk Arbiter ketiga yang akan menjadi Ketua Arbitrase.\r\nb.Apabila salah satu dari para pihak gagal menunjuk Arbiternya dalam jangka waktu sebagaimana dinyatakan di atas, Arbiter yang telah ditunjuk akan duduk sendiri sebagai Arbitrase dan memberikan Keputusan.\r\nc.Namun apabila kedua Arbiter gagal menunjuk Arbiter ketiga dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal penunjukan kedua Arbiter, maka Ketua BANI atau Pejabat BANI yang berwenang akan menunjuk Arbiter ketiga sebagai Ketua Arbiter atas permintaan salah satu pihak.\r\n(3)Para pihak harus menanggung biaya Arbitrase secara sama rata dan proses Arbitrase harus dilangsungkan di Jakarta.\r\n(4)Kecuali dalam ayat (2) sub b. Pasal ini, Keputusan Badan Arbitrase diambil berdasarkan suara terbanyak dan bersifat mengikat kedua belah pihak terhadap para pihak.\r\n(5)Para pihak telah sepakat dan berjanji untuk secara tegas menentukan tidak ada banding atau penghentian pelaksanaan yang diajukan ke Pengadilan atas Keputusan Badan Arbitrase dan para pihak tidak akan menolak atau menentang pelaksanaan keputusan yang dilakukan oleh pihak untuk keuntungan siapa keputusan Badan Arbitrase telah diberikan.\r\n(6)Tiada satu pihak berhak untuk memulai atau melakukan tindakan di Pengadilan terhadap segala masalah dalam sengketa sampai dengan masalah tersebut telah diputuskan sebagaimana diatur di sini, kecuali untuk pelaksanaan keputusan Badan Arbitrase.\r\n(7)Selama proses Arbitrase dan sampai Arbitrase memberikan keputusannya, para pihak setuju untuk terus melaksanakan semua kewajibannya masing-masing berdasarkan Perjanjian ini tanpa berprasangka atau menduga atas putusan akhir yang diambil oleh para Arbiter tersebut.\r\n(8)Para pihak setuju memberlakukan penunjukan tidak akan berakhir pada tanggal setelah 6 (enam) bulan kalender sejak tanggal penunjukannya dan mandat kepada Arbitrase (wasit-wasit) sebagaimana yang ditetapkan sesuai dengan keputusan ini, akan tetap berlangsung sampai keputusan telah diambil oleh Badan Arbitrase.\r\n(9)Keputusan Badan Arbitrase dapat dilaksanakan di setiap Pengadilan dimanapun yang mempunyai yurisdiksi yang berwenang terhadap masing-masing para pihak atau harta kekayaannya.', 2, '2024-03-08 07:55:29', NULL),
(45, 'PASAL 18', 'KETENTUAN MENJAGA RAHASIA', '(1)Para Pihak sepakat melakukan usaha-usaha mereka yang terbaik untuk menjaga kerahasiaan Informasi sehubungan dengan Perjanjian ini dan Para Pihak harus memastikan direktur-direktur, pegawai-pegawai, agen-agen atau pembantu-pembantu mereka tidak akan mengungkapkan informasi, data, dokumentasi dan pengetahuan kepada Pihak Ketiga tanpa persetujuan tertulis dari pihak yang lain, tidak juga akan menerbitkan informasi, data, dokumentasi dan pengetahuan dalam bentuk cetakan, kaset, disket, disk atau bentuk-bentuk lain, kecuali sepanjang tindakan dilakukan sebagai laporan kepada instansi pemerintah terkait sebagaimana diperlukan oleh undang-undang.\r\n(2)Pengecualian Informasi Ketentuan tidak berlaku dalam hal Informasi telah menjadi milik umum atau dengan lewatnya waktu 10 (sepuluh) tahun sejak penandatanganan Perjanjian ini.', 2, '2024-03-08 07:55:29', NULL),
(46, 'PASAL 19', 'PELINDUNGAN DATA PRIBADI', 'Kewajiban Para Pihak dalam upaya Pelindungan Data Pribadi:\r\n(1)Memproses Data Pribadi sesuai Undang-Undang Perlindungan Data Pribadi dan ketentuan dalam Peraturan Perundang-undangan lainnya.\r\n(2)Hanya memproses Data Pribadi apabila dan hanya sejauh diperlukan agar dapat melaksanakan kewajiban berdasarkan Perjanjian; \r\n(3)Tidak mengungkapkan Data Pribadi kepada pihak ketiga mana pun selain:\r\na.Karyawan, direksi, afiliasi berdasarkan kebutuhan (need-to know) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini; \r\nb.Subkontraktor atau penasehat professional yang diizinkan secara tertulis oleh Para Pihak untuk memproses Data Pribadi berdasarkan kebutuhan (need-to know basis) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini; atau \r\nc.Sejauh diperlukan oleh peraturan perundang-undangan yang berlaku, namun tetap memperhatikan dan mematuhi Undang-Undang Perlindungan Data. Dalam hal tersebut, Pihak yang berkepentingan harus memberikan pemberitahuan tertulis kepada Pihak lainnya untuk mengungkapkan Data Pribadi (sejauh diizinkan oleh peraturan perundang-undangan yang berlaku) segera mungkin setelah mengetahui persyaratan tersebut.\r\n(4)Memastikan bahwa personilnya yang memproses Data Pribadi melaksanakan hal tersebut dan tetap patuh terhadap kewajiban kerahasiaan; dan\r\n(5)Melaksanakan dan mempertahankan tindakan atau langkah administratif, teknis dan organisasi yang cukup: \r\na.Untuk menjaga keamanan Data Pribadi; dan \r\nb.Untuk mencegah penghapusan tidak sah atau tidak disengaja, perubahan tidak sah, menyalin, mengakses atau menggunakan, pemalsuan, pencurian, kehilangan atau kesalahan teknis sehubungan dengan Data Pribadi.\r\nPIHAK KESATU maupun PIHAK KEDUA bertanggung jawab atas kerugian terhadap pelanggaran ketentuan terkait Data Pribadi yang diakibatkan oleh kelalaian personilnya serta akan bertanggung jawab penuh, termasuk namun tidak terbatas pada segala klaim, tuntutan, gugatan, sengketa, dan/atau ganti kerugian yang mungkin timbul dari pelanggaran ketentuan terkait Data Pribadi.', 2, '2024-03-08 07:55:29', NULL),
(47, 'PASAL 20', 'HUKUM YANG BERLAKU', 'Perjanjian   ini   tunduk   dan   berada   di   bawah ketentuan hukum Republik Indonesia.', 2, '2024-03-08 07:55:29', NULL),
(48, 'PASAL 21', 'LARANGAN PEMBERIAN HADIAH DAN KOMISI', '(1)PIHAK KEDUA dilarang untuk menerima penawaran atau menyetujui pemberian hadiah, komisi, potongan atau bentuk-bentuk lain yang sejenis dari Direksi, staff/karyawan dari PIHAK KESATU untuk tujuan ditandatanganinya dan/atau pelaksanaan Perjanjian ini.\r\n(2)Pelanggaran terhadap ayat 1 Pasal ini oleh PIHAK KEDUA atau karyawannya atau pihak lain yang bekerja untuk PIHAK KEDUA dapat mengakibatkan pembatalan Perjanjian ini oleh PIHAK KESATU, dan biaya yang timbul dari pembatalan tersebut akan menjadi tanggung jawab PIHAK KEDUA, dan PIHAK KEDUA akan dieliminasi sebagai mitra bisnis PIHAK KESATU.\r\n(3)Pelanggaran dari setiap ketentuan dalam Pasal ini akan mengakibatkan gugatan pidana terhadap PIHAK KEDUA. Dalam hal terjadi penindaklanjutan atas adanya tindakan penerimaan komisi atau hadiah yang berpotensi merugikan PIHAK KESATU, semua biaya, ongkos dan kerugian yang timbul akan menjadi tanggung jawab PIHAK KEDUA. ', 2, '2024-03-08 07:58:04', NULL),
(49, 'PASAL 22', 'TANGGAL BERLAKUNYA PERJANJIAIN', 'Perjanjian ini berlaku efektif terhitung sejak ditandatanganinya Perjanjian ini oleh wakil Para Pihak yang berwenang.', 2, '2024-03-08 07:58:04', NULL),
(50, 'PASAL 23', 'LAMPIRAN - LAMPIRAN', '(1)	Lampiran I 	:  Dokumen-Dokumen Pengadaan\r\n(2)	Lampiran II	:  Lingkup Perjanjian\r\n(3)	Lampiran III	:  Spesifikasi Teknis\r\n(4)	Lampiran IV	:  Jadwal Penyerahan Barang\r\n(5)	Lampiran V	:  Harga Barang\r\n(6)	Lampiran VI	:  Pembayaran\r\n(7)	Lampiran VII	:  Alamat Surat Menyurat\r\n', 2, '2024-03-08 07:58:04', NULL),
(51, 'PASAL 24', 'LAIN - LAIN', '(1)Hal-hal yang belum diatur dan perubahan-perubahan dari Perjanjian ini, akan diselesaikan melalui kesepakatan atau perundingan kedua belah pihak dan yang akan dituangkan dalam suatu Addendum Perjanjian yang ditandatangani oleh kedua belah pihak serta merupakan bagian yang tidak dapat dipisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.\r\n(2)Segala ketentuan-ketentuan dan syarat-syarat dalam Perjanjian ini berlaku serta mengikat bagi pihak-pihak yang menandatangani, pengganti-penggantinya dan mereka yang memperoleh keuntungan dari padanya.\r\n(3)Lampiran Perjanjian merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.', 2, '2024-03-08 07:58:04', NULL),
(52, 'TES INPUT PASAL', 'tes ubah isi pasal', 'seandainya kau tau ku tak ingin kau pergi', 1, '2024-03-17 01:02:39', '2024-03-17 01:18:30');
